import{_ as d,o as r,c as a,a2 as e}from"./chunks/framework.CqpfiAoK.js";const q=JSON.parse('{"title":"আইনি অনুচ্ছেদের সূচি","description":"","frontmatter":{},"headers":[],"relativePath":"bn/92-法律条文索引.md","filePath":"bn/92-法律条文索引.md","lastUpdated":1789183869000}'),h={name:"bn/92-法律条文索引.md"};function o(l,t,i,b,n,u){return r(),a("div",null,[...t[0]||(t[0]=[e('<h1 id="আইনি-অনুচ্ছেদের-সূচি" tabindex="-1">আইনি অনুচ্ছেদের সূচি <a class="header-anchor" href="#আইনি-অনুচ্ছেদের-সূচি" aria-label="Permalink to &quot;আইনি অনুচ্ছেদের সূচি&quot;">​</a></h1><table tabindex="0"><thead><tr><th>আইটেম</th><th>বিষয়বস্তু</th></tr></thead><tbody><tr><td>নথি নম্বর</td><td>92</td></tr><tr><td>মডিউল</td><td>পরিশিষ্ট ও রেফারেন্স উপকরণ</td></tr><tr><td>মূল শব্দগুলি</td><td>আইনি সূচি, সিম্বায়োসিস সংবিধান, শ্রম আইন, ভোক্তা সুরক্ষা আইন, সহায়ক আইন</td></tr></tbody></table><h2 id="১-সূচির-বিবরণ" tabindex="-1">১. সূচির বিবরণ <a class="header-anchor" href="#১-সূচির-বিবরণ" aria-label="Permalink to &quot;১. সূচির বিবরণ&quot;">​</a></h2><p>এই সূচিতে অ্যাঙ্কর সিম্বায়োসিস সভ্যতার বর্তমানে প্রভাববিস্তার প্রধান আইনি নথি এবং তাদের মূল অনুচ্ছেদগুলি অন্তর্ভুক্ত করা হয়েছে, আইনি স্তর এবং বিভাগ অনুযায়ী সাজানো হয়েছে। সূচির পরিসরে &quot;সিম্বায়োসিস সংবিধান&quot;, &quot;সিম্বায়োসিস শ্রম আইন&quot;, &quot;ভোক্তা সুরক্ষা আইন&quot; এবং শিক্ষা, চিকিৎসা, আবাসন, পরিবেশ ও একচেটিয়াবিরোধী পাঁচটি সহায়ক আইন অন্তর্ভুক্ত। প্রতিটি সূচি প্রবেশে আইনের নাম, অনুচ্ছেদ নম্বর এবং অনুচ্ছেদের মূল বিষয়বস্তুর সারাংশ তালিকাভুক্ত করা হয়েছে। এই সূচিটি একটি রেফারেন্স টুল; আইনি অনুচ্ছেদের সম্পূর্ণ পাঠ এবং বিচারিক ব্যাখ্যার জন্য প্রতিটি আইনের অফিসিয়াল পাঠ দেখুন।</p><h2 id="২-সিম্বায়োসিস-সংবিধান" tabindex="-1">২. সিম্বায়োসিস সংবিধান <a class="header-anchor" href="#২-সিম্বায়োসিস-সংবিধান" aria-label="Permalink to &quot;২. সিম্বায়োসিস সংবিধান&quot;">​</a></h2><p>&quot;সিম্বায়োসিস সংবিধান&quot; অ্যাঙ্কর সিম্বায়োসিস সভ্যতার মৌলিক আইন, সর্বোচ্চ আইনি প্রভাব সহ, সিম্বায়োসিস সভ্যতার আনুষ্ঠানিক প্রতিষ্ঠার সময় প্রণীত হয়েছিল।</p><table tabindex="0"><thead><tr><th>অনুচ্ছেদ নম্বর</th><th>মূল বিষয়বস্তু</th></tr></thead><tbody><tr><td>প্রথম অনুচ্ছেদ</td><td>হেঙ্গুয়ানঝো (ওয়ানলিং হেঙ্গমাও উৎস ব্রহ্মাণ্ড)কে অ্যাঙ্কর সিম্বায়োসিস সভ্যতার শাসন ক্ষেত্র হিসেবে প্রতিষ্ঠিত; সিম্বায়োসিস সভ্যতার মৌলিক উদ্দেশ্য হলো সমস্ত জাতির সিম্বায়োসিস এবং মহাজাগতিক মাত্রা উন্নয়ন অর্জন করা</td></tr><tr><td>দ্বিতীয় অনুচ্ছেদ</td><td>সম্পদ-অপহরণবিরোধীবাদকে সভ্যতার মৌলিক অবস্থান হিসেবে প্রতিষ্ঠিত; যেকোনো রূপের সম্পদ-অপহরণ শৈলীর সাধনা এবং সম্পদ অপহরণ নিষিদ্ধ</td></tr><tr><td>তৃতীয় অনুচ্ছেদ</td><td>&quot;নিয়তি এবং বিবর্তনের নির্বাচনের অধিকার সব সত্ত্বের কাছে ফেরত দেওয়া&quot;কে সভ্যতার মূল ধারণা হিসেবে প্রতিষ্ঠিত</td></tr><tr><td>চতুর্থ অনুচ্ছেদ</td><td>বেশি কাজ বেশি লাভ, স্ব-বৃদ্ধি, প্রত্যেকের পথ আছে, সমস্ত জাতি একসাথে অগ্রসর হয়কে সভ্যতার মৌলিক নীতি হিসেবে প্রতিষ্ঠিত</td></tr><tr><td>পঞ্চম অনুচ্ছেদ</td><td>তিনশত সেটের উৎস সাধনা পদ্ধতির বিনামূল্যে উন্মুক্তকরণ ব্যবস্থা প্রতিষ্ঠিত; কোনো সংস্থা বা ব্যক্তি সাধনা পদ্ধতির প্রেরণের অধিকার একচেটিয়া করতে পারবে না</td></tr><tr><td>ষষ্ঠ অনুচ্ছেদ</td><td>যৌথ উৎপাদন চুক্তি প্রক্রিয়াকে মৌলিক সম্পদ বণ্টন ব্যবস্থা হিসেবে প্রতিষ্ঠিত</td></tr><tr><td>সপ্তম অনুচ্ছেদ</td><td>20% সক্রিয়করণ কৌশলকে পর্যায়ক্রমিক জাতীয় লক্ষ্য হিসেবে প্রতিষ্ঠিত</td></tr><tr><td>অষ্টম অনুচ্ছেদ</td><td>বাস্তবতা-ভিত্তিক নীতি প্রতিষ্ঠিত; বাস্তব বিশ্বই একমাত্র বাস্তব বিশ্ব, কাল্পনিক সেটিংসের কোনো আইনি প্রভাব নেই</td></tr><tr><td>নবম অনুচ্ছেদ</td><td>চার-পর্যায়ের মাত্রা উন্নয়ন পথকে সভ্যতার দীর্ঘমেয়াদী উন্নয়ন কৌশল হিসেবে প্রতিষ্ঠিত</td></tr><tr><td>দশম অনুচ্ছেদ</td><td>সমস্ত জাতির সমতার নীতি প্রতিষ্ঠিত; সমস্ত জীবের রূপ আইনের সামনে সমানভাবে সমান</td></tr><tr><td>একাদশ অনুচ্ছেদ</td><td>সিম্বায়োসিস বিবর্তনের নীতি প্রতিষ্ঠিত; পৃথক বিবর্তন অন্য পৃথক বা সমষ্টিগত বিবর্তনের অধিকারের ক্ষতির বিনিময়ে হতে পারবে না</td></tr><tr><td>দ্বাদশ অনুচ্ছেদ</td><td>বেশি কাজ বেশি লাভের নীতি প্রতিষ্ঠিত; সম্পদ বণ্টনে অবদানকে মূল ভিত্তি হিসেবে গ্রহণ করা হয়</td></tr><tr><td>ত্রয়োদশ অনুচ্ছেদ</td><td>স্ব-বৃদ্ধির নীতি প্রতিষ্ঠিত; প্রতিটি জীবের স্বায়ত্তশাসিত বিবর্তন নির্বাচনের অধিকারকে সম্মান করা হয়</td></tr><tr><td>চতুর্দশ অনুচ্ছেদ</td><td>প্রত্যেকের পথ আছে নীতি প্রতিষ্ঠিত; রাষ্ট্রের প্রতিটি জীবকে মৌলিক বিবর্তন পথ এবং সম্পদ নিশ্চিতকরণ প্রদানের বাধ্যতা রয়েছে</td></tr><tr><td>পঞ্চদশ অনুচ্ছেদ</td><td>টেকসইতার নীতি প্রতিষ্ঠিত; সমস্ত উন্নয়ন অবশ্যই মহাজাগতিক উৎসের টেকসইতাকে বিবেচনা করবে</td></tr><tr><td>ষোড়শ-পঁচিশ অনুচ্ছেদ</td><td>সব সত্ত্বের মৌলিক অধিকার নির্ধারণ: বিবর্তন নির্বাচনের অধিকার, সাধনা সম্পদ প্রাপ্তির অধিকার, সমান সুরক্ষার অধিকার, সিম্বায়োসিস অংশগ্রহণের অধিকার, সাংস্কৃতিক সংরক্ষণের অধিকার, ত্রাণ এবং আপিলের অধিকার, ব্যক্তিগত স্বাধীনতার অধিকার, ব্যক্তিগত মর্যাদার অধিকার, বিশ্বাস স্বাধীনতার অধিকার, অভিব্যক্তি স্বাধীনতার অধিকার</td></tr><tr><td>ছাব্বিশ-একত্রিশ অনুচ্ছেদ</td><td>সব সত্ত্বের মৌলিক কর্তব্য নির্ধারণ: আইন মানার কর্তব্য, সিম্বায়োসিস শৃঙ্খলা বজায় রাখার কর্তব্য, শ্রম অবদানের কর্তব্য, পরিবেশ সুরক্ষার কর্তব্য, অন্যের অধিকার সম্মান করার কর্তব্য, প্রাথমিক সাধকদের নির্দেশনা দেওয়ার কর্তব্য</td></tr><tr><td>বত্রিশ অনুচ্ছেদ</td><td>অ্যাঙ্কর কাউন্সিলকে সর্বোচ্চ কর্তৃপক্ষ হিসেবে প্রতিষ্ঠিত, সমস্ত জাতির প্রতিনিধি অনুপাতে গঠিত</td></tr><tr><td>তেত্রিশ অনুচ্ছেদ</td><td>সিম্বায়োসিস কার্যকরী কমিটিকে সর্বোচ্চ প্রশাসনিক অঙ্গ হিসেবে প্রতিষ্ঠিত</td></tr><tr><td>চৌত্রিশ অনুচ্ছেদ</td><td>সিম্বায়োসিস আদালতকে সর্বোচ্চ বিচারিক অঙ্গ হিসেবে প্রতিষ্ঠিত, স্বাধীনভাবে বিচার ক্ষমতা প্রয়োগ করে</td></tr><tr><td>পঁয়ত্রিশ অনুচ্ছেদ</td><td>অ্যাঙ্কর তদারকি কমিটিকে স্বাধীন তদারকি অঙ্গ হিসেবে প্রতিষ্ঠিত</td></tr><tr><td>ছত্রিশ অনুচ্ছেদ</td><td>আইন প্রণয়ন প্রক্রিয়া নির্ধারণ: বিলগুলি অ্যাঙ্কর কাউন্সিলের অর্ধেকের বেশি সংখ্যাগরিষ্ঠতা দ্বারা পাস হয়</td></tr><tr><td>সঁত্রিশ অনুচ্ছেদ</td><td>সংবিধান সংশোধন প্রক্রিয়া নির্ধারণ: অবশ্যই অ্যাঙ্কর কাউন্সিলের দুই-তৃতীয়াংশের বেশি সংখ্যাগরিষ্ঠতা দ্বারা পাস হতে হবে এবং জাতীয় গণভোটের অর্ধেকের বেশি সম্মতি প্রাপ্ত করতে হবে</td></tr><tr><td>অষ্টত্রিশ অনুচ্ছেদ</td><td>সাংবিধানিক পর্যালোচনা ব্যবস্থা প্রতিষ্ঠিত; সিম্বায়োসিস আদালতের সংবিধান লঙ্ঘনকারী আইনকে অকার্যকর ঘোষণা করার অধিকার রয়েছে</td></tr><tr><td>ঊনত্রিশ অনুচ্ছেদ</td><td>সাংবিধানিক মামলা ব্যবস্থা প্রতিষ্ঠিত; সব সত্ত্ব সরাসরি সংবিধানের ভিত্তিতে মামলা দায়ের করতে পারে</td></tr><tr><td>ত্রিশ অনুচ্ছেদ</td><td>স্থানীয় স্বায়ত্তশাসন ব্যবস্থা নির্ধারণ; প্রতিটি নক্ষত্র ডোমেইন এবং প্রতিটি সমতল সংবিধানের কাঠামোর মধ্যে স্বায়ত্তশাসন প্রয়োগ করে</td></tr><tr><td>একত্রিশ অনুচ্ছেদ</td><td>সমস্ত জাতির প্রজাতন্ত্র ব্যবস্থা প্রতিষ্ঠিত; সমস্ত জাতি সিম্বায়োসিস সভ্যতায় সমানভাবে সমান, আঞ্চলিক স্বায়ত্তশাসন প্রয়োগ করে</td></tr><tr><td>দ্বাত্রিশ অনুচ্ছেদ</td><td>সিম্বায়োসিস সভ্যতার অর্থনৈতিক ব্যবস্থা নির্ধারণ: যৌথ উৎপাদন চুক্তিকে ভিত্তি করে, বহু মালিকানার অর্থননীতি একসাথে উন্নয়ন করে</td></tr><tr><td>ত্রয়োত্রিশ অনুচ্ছেদ</td><td>সাধনা সম্পদের রাষ্ট্রীয় মালিকানা এবং ন্যায়সঙ্গত বণ্টন ব্যবস্থা নির্ধারণ</td></tr><tr><td>চতুর্ত্রিশ অনুচ্ছেদ</td><td>শিক্ষা ন্যায়সঙ্গতা ব্যবস্থা প্রতিষ্ঠিত, প্রতিটি জীবের সমান শিক্ষার অধিকার নিশ্চিত করে</td></tr><tr><td>পঁয়ত্রিশ অনুচ্ছেদ</td><td>সর্বজনীন চিকিৎসা নিরাপত্তা ব্যবস্থা প্রতিষ্ঠিত</td></tr><tr><td>ছত্রিশ অনুচ্ছেদ</td><td>আবাসন নিরাপত্তা ব্যবস্থা প্রতিষ্ঠিত, প্রতিটি জীবের মৌলিক আবাসনের অধিকার নিশ্চিত করে</td></tr><tr><td>সঁত্রিশ অনুচ্ছেদ</td><td>আন্তঃ-সমতল মিথস্ক্রিয়ার মৌলিক নীতি নির্ধারণ; অনুমতি ছাড়া কোনো অননুমোদিত আন্তঃ-সমতল ভ্রমণ যাবে না</td></tr><tr><td>অষ্টত্রিশ অনুচ্ছেদ</td><td>প্রত্নতাত্ত্বিক কার্যক্রমের বৈধ আউটপুট শুধুমাত্র বিমূর্ত জ্ঞান এবং তথ্যে সীমাবদ্ধ, পদার্থ এবং শক্তির ফেরত নিষিদ্ধ</td></tr><tr><td>ঊনত্রিশ অনুচ্ছেদ</td><td>সময় প্রত্যাবর্তনের মৌলিক নীতি নির্ধারণ; অবশ্যই প্রথমে পর্যবেক্ষণ, তারপর সীমিত হস্তক্ষেপের নীতি অনুসরণ করতে হবে</td></tr><tr><td>চল্লিশ অনুচ্ছেদ</td><td>সংবিধানের ব্যাখ্যার অধিকার সিম্বায়োসিস আদালতের অন্তর্গত, এবং সংবিধান সংশোধনের অধিকার অ্যাঙ্কর কাউন্সিলের অন্তর্গত</td></tr></tbody></table><h2 id="৩-সিম্বায়োসিস-শ্রম-আইন" tabindex="-1">৩. সিম্বায়োসিস শ্রম আইন <a class="header-anchor" href="#৩-সিম্বায়োসিস-শ্রম-আইন" aria-label="Permalink to &quot;৩. সিম্বায়োসিস শ্রম আইন&quot;">​</a></h2><p>&quot;সিম্বায়োসিস শ্রম আইন&quot; শ্রম সম্পর্ক নিয়ন্ত্রণ এবং শ্রমিকদের অধিকার-সুবিধা সুরক্ষার মৌলিক আইন, সিম্বায়োসিস সংবিধানের চতুর্দশ অনুচ্ছেদকে আইনি ভিত্তি হিসেবে গ্রহণ করে।</p><table tabindex="0"><thead><tr><th>অনুচ্ছেদ নম্বর</th><th>মূল বিষয়বস্তু</th></tr></thead><tbody><tr><td>প্রথম অনুচ্ছেদ</td><td>আইনি উদ্দেশ্য: শ্রম সম্পর্ক নিয়ন্ত্রণ, শ্রমিকদের বৈধ অধিকার-সুবিধা সুরক্ষা, এবং সামঞ্জস্যপূর্ণ এবং সিম্বায়োসিস শ্রম সম্পর্ক গঠন করা</td></tr><tr><td>দ্বিতীয় অনুচ্ছেদ</td><td>প্রয়োগের পরিসর: হেঙ্গুয়ানঝোতে সমস্ত শ্রম সম্পর্ক, পদার্থ শ্রম, সাধনা শ্রম এবং সৃজনশীল শ্রম অন্তর্ভুক্ত</td></tr><tr><td>তৃতীয় অনুচ্ছেদ</td><td>শ্রমিকদের সমান নিয়োগের নীতি প্রতিষ্ঠিত; জাতি, লিঙ্গ, সাধনা স্তর বা উৎসের ভিত্তিতে নিয়োগ বৈষম্য নিষিদ্ধ</td></tr><tr><td>চতুর্থ অনুচ্ছেদ</td><td>শ্রমিকদের স্বাধীন পেশা নির্বাচনের নীতি প্রতিষ্ঠিত; জোরপূর্বক শ্রম এবং দাসত্ব নিষিদ্ধ</td></tr><tr><td>পঞ্চম অনুচ্ছেদ</td><td>শ্রম চুক্তি ব্যবস্থা নির্ধারণ; শ্রম সম্পর্ক স্থাপনের সময় একটি লিখিত শ্রম চুক্তি সম্পাদন করা উচিত</td></tr><tr><td>ষষ্ঠ অনুচ্ছেদ</td><td>শ্রম চুক্তির প্রয়োজনীয় শর্তাবলী নির্ধারণ: চুক্তির মেয়াদ, কাজের বিষয়বস্তু, শ্রম পারিশ্রমিক, কাজের সময়, শ্রম সুরক্ষা, সামাজিক বীমা</td></tr><tr><td>সপ্তম অনুচ্ছেদ</td><td>আট ঘণ্টার কর্মসূচি এবং প্রতি সপ্তাহে চল্লিশচার ঘণ্টার বেশি নয় এমন কর্মসূচি প্রতিষ্ঠিত</td></tr><tr><td>অষ্টম অনুচ্ছেদ</td><td>ওভারটাইম সীমাবদ্ধতা নির্ধারণ: দৈনিক ওভারটাইম এক ঘণ্টার বেশি হবে না, বিশেষ পরিস্থিতিতে তিন ঘণ্টার বেশি হবে না, মাসিক ওভারটাইম ছত্রিশ ঘণ্টার বেশি হবে না</td></tr><tr><td>নবম অনুচ্ছেদ</td><td>ওভারটাইম মজুরির মান নির্ধারণ: কর্মদিবসে ওভারটাইমে 1.5 গুণ মজুরি, বিশ্রাম দিবসে ওভারটাইমে 2 গুণ মজুরি, আইনি ছুটির দিনে ওভারটাইমে 3 গুণ মজুরি</td></tr><tr><td>দশম অনুচ্ছেদ</td><td>সর্বনিম্ন মজুরি নিরাপত্তা ব্যবস্থা প্রতিষ্ঠিত; সর্বনিম্ন মজুরির মান প্রতিটি নক্ষত্র ডোমেইন স্থানীয় পরিস্থিতি অনুযায়ী প্রণয়ন করে</td></tr><tr><td>একাদশ অনুচ্ছেদ</td><td>মজুরি প্রদান ব্যবস্থা নির্ধারণ: মজুরি মাসিকভাবে শ্রমিকদের নিকট মুদ্রার রূপে প্রদান করা উচিত, এবং কাটা বা অযথা বিলম্বিত করা যাবে না</td></tr><tr><td>দ্বাদশ অনুচ্ছেদ</td><td>বেশি কাজ বেশি লাভের বণ্টন নীতি প্রতিষ্ঠিত; কাজের ভিত্তিতে বণ্টনকে মূল অংশ হিসেবে এবং বহু বণ্টন পদ্ধতির সহাবস্থানের সাথে একটি বণ্টন ব্যবস্থা প্রয়োগ করা হয়</td></tr><tr><td>ত্রয়োদশ অনুচ্ছেদ</td><td>শ্রম নিরাপত্তা এবং স্বাস্থ্য ব্যবস্থা নির্ধারণ; নিয়োগকর্তাদের অবশ্যই শ্রমিকদের জন্য মান অনুযায়ী শ্রম নিরাপত্তা এবং স্বাস্থ্য অবস্থা প্রদান করতে হবে</td></tr><tr><td>চতুর্দশ অনুচ্ছেদ</td><td>বিশেষ গোষ্ঠীর সুরক্ষা নির্ধারণ: অপ্রাপ্তবয়স্ক শ্রমিক, মহিলা শ্রমিক, প্রতিবন্ধী শ্রমিক এবং নিম্ন-সাধনা শ্রমিকদের জন্য বিশেষ শ্রম সুরক্ষা</td></tr><tr><td>পঞ্চদশ অনুচ্ছেদ</td><td>পেশাদার প্রশিক্ষণ ব্যবস্থা প্রতিষ্ঠিত; নিয়োগকর্তাদের শ্রমিকদের জন্য পেশাদার দক্ষতা প্রশিক্ষণ আয়োজনের বাধ্যতা রয়েছে</td></tr><tr><td>ষোড়শ অনুচ্ছেদ</td><td>সাধকদের শ্রম অধিকার-সুবিধা নির্ধারণ: সাধনা শ্রমও এই আইন দ্বারা সুরক্ষিত; সাধনা ফলাফলের মালিকানা চুক্তি দ্বারা সম্মত হয়</td></tr><tr><td>সপ্তদশ অনুচ্ছেদ</td><td>শ্রমিকদের সামাজিক বীমা ব্যবস্থা প্রতিষ্ঠিত: পেনশন বীমা, চিকিৎসা বীমা, বেকারত্ব বীমা, কর্মসংক্রান্ত আঘাত বীমা, প্রসূতি বীমা</td></tr><tr><td>অষ্টাদশ অনুচ্ছেদ</td><td>শ্রমিকদের কল্যাণ ব্যবস্থা নির্ধারণ: নিয়োগকর্তাদের শ্রমিকদের জন্য প্রয়োজনীয় কল্যাণ সুবিধা প্রদান করা উচিত</td></tr><tr><td>ঊনবিংশ অনুচ্ছেদ</td><td>শ্রম বিবাদ পরিচালনা ব্যবস্থা প্রতিষ্ঠিত: আলোচনা, মধ্যস্থতা, সালিশ এবং বিচারের চার-স্তরের পরিচালনা প্রক্রিয়া</td></tr><tr><td>বিংশ অনুচ্ছেদ</td><td>ট্রেড ইউনিয়ন ব্যবস্থা নির্ধারণ; শ্রমিকদের আইন অনুযায়ী ট্রেড ইউনিয়ন গঠন এবং যোগদানের অধিকার রয়েছে তাদের বৈধ অধিকার-সুবিধা রক্ষার জন্য</td></tr><tr><td>একবিংশ অনুচ্ছেদ</td><td>সমষ্টিগত চুক্তি ব্যবস্থা নির্ধারণ; ট্রেড ইউনিয়ন কর্মচারীদের প্রতিনিধিত্ব করে নিয়োগকর্তাদের সাথে সমষ্টিগত চুক্তি সম্পাদন করে</td></tr><tr><td>দ্বিবিংশ অনুচ্ছেদ</td><td>নিয়োগকর্তাদের নিয়ম-কানুন অবশ্যই কর্মচারী প্রতিনিধি কংগ্রেস বা সমস্ত কর্মচারীর আলোচনার বিষয় হবে</td></tr><tr><td>ত্রিবিংশ অনুচ্ছেদ</td><td>শ্রম চুক্তি সমাপ্তির শর্তাবলী এবং প্রক্রিয়া নির্ধারণ</td></tr><tr><td>চতুর্বিংশ অনুচ্ছেদ</td><td>আর্থিক ক্ষতিপূরণ ব্যবস্থা নির্ধারণ; নিয়োগকর্তাদের আইন অনুযায়ী শ্রম চুক্তি সমাপ্তির সময় আর্থিক ক্ষতিপূরণ প্রদান করতে হবে</td></tr><tr><td>পঞ্চবিংশ অনুচ্ছেদ</td><td>অবৈধভাবে শ্রম চুক্তি সমাপ্তির ক্ষতিপূরণ ব্যবস্থা নির্ধারণ</td></tr><tr><td>ছবিংশ অনুচ্ছেদ</td><td>শ্রম প্রেরণ ব্যবস্থাপনা ব্যবস্থা প্রতিষ্ঠিত, শ্রম প্রেরণ নিয়োগ নিয়ন্ত্রণ করে</td></tr><tr><td>সপ্তবিংশ অনুচ্ছেদ</td><td>খণ্ডকালীন নিয়োগের বিশেষ নিয়ম নির্ধারণ</td></tr><tr><td>অষ্টবিংশ অনুচ্ছেদ</td><td>তদারকি এবং পরিদর্শন ব্যবস্থা নির্ধারণ; শ্রম প্রশাসনিক বিভাগগুলি আইন অনুযায়ী নিয়োগকর্তাদের শ্রম আইন-কানুন মানানোর বিষয়ে তদারকি এবং পরিদর্শন করে</td></tr><tr><td>ঊনত্রিশ অনুচ্ছেদ</td><td>আইনি দায়িত্ব নির্ধারণ: এই আইন লঙ্ঘনকারী নিয়োগকর্তারা আইন অনুযায়ী প্রশাসনিক, বেসরকারি এবং ফৌজদারি দায়িত্ব গ্রহণ করবে</td></tr><tr><td>ত্রিশ অনুচ্ছেদ</td><td>এই আইনের প্রভাববিস্তার তারিখ এবং ব্যাখ্যার অধিকার নির্ধারণ</td></tr></tbody></table><h2 id="৪-ভোক্তা-সুরক্ষা-আইন" tabindex="-1">৪. ভোক্তা সুরক্ষা আইন <a class="header-anchor" href="#৪-ভোক্তা-সুরক্ষা-আইন" aria-label="Permalink to &quot;৪. ভোক্তা সুরক্ষা আইন&quot;">​</a></h2><p>&quot;ভোক্তা সুরক্ষা আইন&quot; ভোক্তাদের বৈধ অধিকার-সুবিধা সুরক্ষা এবং ব্যবসায়ীদের আচরণ নিয়ন্ত্রণের মৌলিক আইন।</p><table tabindex="0"><thead><tr><th>অনুচ্ছেদ নম্বর</th><th>মূল বিষয়বস্তু</th></tr></thead><tbody><tr><td>প্রথম অনুচ্ছেদ</td><td>আইনি উদ্দেশ্য: ভোক্তাদের বৈধ অধিকার-সুবিধা সুরক্ষা, সামাজিক ও অর্থনৈতিক শৃঙ্খলা বজায় রাখা, এবং সিম্বায়োসিস বাজার অর্থনীতির সুস্থ উন্নয়ন প্রচার করা</td></tr><tr><td>দ্বিতীয় অনুচ্ছেদ</td><td>প্রয়োগের পরিসর: হেঙ্গুয়ানঝোতে দৈনন্দিন ভোগের প্রয়োজনে পণ্য ক্রয়, ব্যবহার বা সেবা গ্রহণকারী ভোক্তাদের অধিকার-সুবিধার সুরক্ষা</td></tr><tr><td>তৃতীয় অনুচ্ছেদ</td><td>ব্যবসায়ী এবং ভোক্তাদের লেনদেনের মৌলিক নীতি প্রতিষ্ঠিত: স্বেচ্ছাচারীতা, সমতা, ন্যায়সঙ্গতা, সততা এবং বিশ্বাসযোগ্যতা</td></tr><tr><td>চতুর্থ অনুচ্ছেদ</td><td>ভোক্তাদের বৈধ অধিকার-সুবিধার রাষ্ট্রীয় সুরক্ষার নীতি প্রতিষ্ঠিত; রাষ্ট্র ভোক্তাদের আইন অনুযায়ী তাদের অধিকার প্রয়োগ নিশ্চিত করতে ব্যবস্থা গ্রহণ করে</td></tr><tr><td>পঞ্চম অনুচ্ছেদ</td><td>ভোক্তাদের নয়টি মৌলিক অধিকার নির্ধারণ: নিরাপত্তার অধিকার, জানার অধিকার, স্বাধীন নির্বাচনের অধিকার, ন্যায়সঙ্গত বাণিজ্যের অধিকার, ক্ষতিপূরণ দাবির অধিকার, সমিতি গঠনের অধিকার, জ্ঞান অর্জনের অধিকার, সম্মানিত হওয়ার অধিকার, তদারকির অধিকার</td></tr><tr><td>ষষ্ঠ অনুচ্ছেদ</td><td>ভোক্তাদের নিরাপত্তার অধিকার নির্ধারণ: ভোক্তারা পণ্য ক্রয়, ব্যবহার এবং সেবা গ্রহণের সময় ব্যক্তিগত এবং সম্পত্তি নিরাপত্তার ক্ষতি না হওয়ার অধিকার উপভোগ করে</td></tr><tr><td>সপ্তম অনুচ্ছেদ</td><td>ভোক্তাদের জানার অধিকার নির্ধারণ: ভোক্তারা তারা ক্রয় বা ব্যবহার করা পণ্য বা গ্রহণ করা সেবার প্রকৃত অবস্থা জানার অধিকার উপভোগ করে</td></tr><tr><td>অষ্টম অনুচ্ছেদ</td><td>ভোক্তাদের স্বাধীন নির্বাচনের অধিকার নির্ধারণ: ভোক্তারা পণ্য বা সেবা স্বাধীনভাবে নির্বাচন করার অধিকার উপভোগ করে</td></tr><tr><td>নবম অনুচ্ছেদ</td><td>ভোক্তাদের ন্যায়সঙ্গত বাণিজ্যের অধিকার নির্ধারণ: ভোক্তারা ন্যায়সঙ্গত বাণিজ্যের অধিকার উপভোগ করে এবং জোরপূর্বক বাণিজ্য আচরণ প্রত্যাখ্যান করার অধিকার রয়েছে</td></tr><tr><td>দশম অনুচ্ছেদ</td><td>ভোক্তাদের ক্ষতিপূরণ দাবির অধিকার নির্ধারণ: পণ্য ক্রয়, ব্যবহার বা সেবা গ্রহণের কারণে ব্যক্তিগত বা সম্পত্তি ক্ষতিগ্রস্ত ভোক্তারা আইন অনুযায়ী ক্ষতিপূরণ পাওয়ার অধিকার উপভোগ করে</td></tr><tr><td>একাদশ অনুচ্ছেদ</td><td>ব্যবসায়ীদের মৌলিক কর্তব্য নির্ধারণ: আইনি এবং চুক্তিগত কর্তব্য পালন, তদারকি গ্রহণ, নিরাপত্তা নিশ্চিত, সত্য তথ্য প্রদান, ভাউচার জারি, মান নিশ্চিত, তিন-নিশ্চয়তা পালন, অন্যায় বাণিজ্য করা যাবে না, ব্যক্তিত্ব লঙ্ঘন করা যাবে না</td></tr><tr><td>দ্বাদশ অনুচ্ছেদ</td><td>ব্যবসায়ীদের নিরাপত্তা নিশ্চিতকরণের কর্তব্য নির্ধারণ: ব্যবসায়ীদের তাদের প্রদান করা পণ্য বা সেবা ব্যক্তিগত এবং সম্পত্তি নিরাপত্তা সুরক্ষার প্রয়োজনীয়তা পূরণ করে তা নিশ্চিত করতে হবে</td></tr><tr><td>ত্রয়োদশ অনুচ্ছেদ</td><td>ব্যবসায়ীদের তথ্য প্রকাশের কর্তব্য নির্ধারণ: ব্যবসায়ীদের ভোক্তাদের কাছে পণ্য বা সেবা সম্পর্কে সত্য তথ্য প্রদান করতে হবে, এবং মিথ্যা বা বিভ্রান্তিকর প্রচার করা যাবে না</td></tr><tr><td>চতুর্দশ অনুচ্ছেদ</td><td>সাধনা পণ্য এবং সেবার বিশেষ মানদণ্ড নির্ধারণ: সাধনা পদ্ধতি, সাধনা যন্ত্র এবং শক্তি পণ্যের ব্যবসায়ীদের বিশেষ যোগ্যতা থাকতে হবে, পণ্যগুলি নিরাপত্তা সার্টিফিকেশন পাস করতে হবে</td></tr><tr><td>পঞ্চদশ অনুচ্ছেদ</td><td>মানক শর্তাবলীর নিয়ন্ত্রণ নির্ধারণ: ব্যবসায়ীরা মানক শর্তাবলীর মাধ্যমে ভোক্তাদের অধিকার বাদ বা সীমাবদ্ধ করতে পারবে না, ব্যবসায়ীদের দায়িত্ব হ্রাস বা ছাড় করতে পারবে না</td></tr><tr><td>ষোড়শ অনুচ্ছেদ</td><td>সাত দিনের অকারণ-ব্যতীত রিটার্ন ব্যবস্থা নির্ধারণ: ইন্টারনেটের মতো দূরবর্তী পদ্ধতিতে পণ্য ক্রয়কারী ভোক্তাদের পণ্য প্রাপ্তির তারিখ থেকে সাত দিনের মধ্যে রিটার্ন করার অধিকার রয়েছে</td></tr><tr><td>সপ্তদশ অনুচ্ছেদ</td><td>তিন-নিশ্চয়তা ব্যবস্থা নির্ধারণ: ব্যবসায়ীদের প্রদান করা পণ্য বা সেবা মানের প্রয়োজনীয়তা পূরণ না করলে, ভোক্তারা রাষ্ট্রীয় বিধান অনুযায়ী মেরামত, প্রতিস্থাপন বা রিটার্নের দাবি করতে পারে</td></tr><tr><td>অষ্টাদশ অনুচ্ছেদ</td><td>শাস্তিমূলক ক্ষতিপূরণ ব্যবস্থা নির্ধারণ: ব্যবসায়ীদের পণ্য বা সেবা প্রদানে প্রতারণামূলক আচরণ থাকলে, তারা ভোক্তাদের দাবি অনুযায়ী ভোক্তাদের ক্ষতির ক্ষতিপূরণ বাড়াতে হবে, এবং বর্ধিত ক্ষতিপূরণের পরিমাণ হবে ভোক্তাদের ক্রয়কৃত পণ্যের মূল্য বা গ্রহণকৃত সেবার খরচের তিন গুণ</td></tr><tr><td>ঊনবিংশ অনুচ্ছেদ</td><td>ভোক্তা সংগঠন নির্ধারণ: ভোক্তা সমিতি এবং অন্যান্য ভোক্তা সংগঠনগুলি আইন অনুযায়ী প্রতিষ্ঠিত সামাজিক সংগঠন যা পণ্য এবং সেবার উপর সামাজিক তদারকি করে ভোক্তাদের বৈধ অধিকার-সুবিধা রক্ষা করে</td></tr><tr><td>বিংশ অনুচ্ছেদ</td><td>ভোক্তা বিবাদ সমাধানের চ্যানেল নির্ধারণ: ব্যবসায়ীদের সাথে আলোচনা সেটলমেন্ট, ভোক্তা সমিতির মধ্যস্থতা অনুরোধ, প্রাসঙ্গিক প্রশাসনিক বিভাগে আপিল, সালিশের জন্য আবেদন, আদালতে মামলা দায়ের</td></tr><tr><td>একবিংশ অনুচ্ছেদ</td><td>বিবাদে প্রমাণের বোঝার বিপরীত নির্ধারণ: টেকসই পণ্য বা সাজসজ্জার মতো সেবার জন্য, ভোক্তারা গ্রহণের তারিখ থেকে ছয় মাসের মধ্যে ত্রুটি খুঁজে পেলে, ব্যবসায়ী প্রমাণের বোঝা বহন করবে</td></tr><tr><td>দ্বিবিংশ অনুচ্ছেদ</td><td>ব্যবসায়ীদের প্রশাসনিক এবং ফৌজদারি দায়িত্ব নির্ধারণ</td></tr><tr><td>ত্রিবিংশ অনুচ্ছেদ</td><td>এই আইনের প্রভাববিস্তার তারিখ এবং ব্যাখ্যার অধিকার নির্ধারণ</td></tr></tbody></table><h2 id="৫-পাঁচটি-সহায়ক-আইন" tabindex="-1">৫. পাঁচটি সহায়ক আইন <a class="header-anchor" href="#৫-পাঁচটি-সহায়ক-আইন" aria-label="Permalink to &quot;৫. পাঁচটি সহায়ক আইন&quot;">​</a></h2><h3 id="৫-১-শিক্ষা-নিরাপত্তা-আইন" tabindex="-1">৫.১ শিক্ষা নিরাপত্তা আইন <a class="header-anchor" href="#৫-১-শিক্ষা-নিরাপত্তা-আইন" aria-label="Permalink to &quot;৫.১ শিক্ষা নিরাপত্তা আইন&quot;">​</a></h3><table tabindex="0"><thead><tr><th>অনুচ্ছেদ নম্বর</th><th>মূল বিষয়বস্তু</th></tr></thead><tbody><tr><td>প্রথম অনুচ্ছেদ</td><td>আইনি উদ্দেশ্য: সব সত্ত্বের সমান শিক্ষার অধিকার নিশ্চিত করা, সিম্বায়োসিস শিক্ষা ব্যবস্থা গঠন করা, এবং সমস্ত জাতির সংস্কৃতির সম্মিলিত উন্নয়ন প্রচার করা</td></tr><tr><td>দ্বিতীয়-পঞ্চম অনুচ্ছেদ</td><td>শিক্ষা ন্যায়সঙ্গতা নীতি, শিক্ষা বিনামূল্যে নীতি (মৌলিক শিক্ষা পর্যায়ে), শিক্ষা বৈচিত্র্য নীতি, শিক্ষা উদ্ভাবন নীতি প্রতিষ্ঠিত</td></tr><tr><td>ষষ্ঠ-দশম অনুচ্ছেদ</td><td>প্রি-স্কুল শিক্ষা, বাধ্যতামূলক শিক্ষা, উচ্চ বিদ্যালয় পর্যায়ের শিক্ষা, উচ্চ শিক্ষা, সাধনা শিক্ষার ব্যবস্থাপনা কাঠামো নির্ধারণ</td></tr><tr><td>একাদশ-পঞ্চদশ অনুচ্ছেদ</td><td>সাধনা শিক্ষার বিশেষ ব্যবস্থা নির্ধারণ: তিনশত সেটের পদ্ধতির শিক্ষা মানদণ্ড, গুরু ব্যবস্থা, সাধনা সম্পদ বরাদ্দ ব্যবস্থা</td></tr><tr><td>ষোড়শ-বিংশ অনুচ্ছেদ</td><td>শিক্ষকদের অধিকার-কর্তব্য, শিক্ষক যোগ্যতা ব্যবস্থা, শিক্ষক চিকিত্সা নিরাপত্তা নির্ধারণ</td></tr><tr><td>একবিংশ-পঞ্চবিংশ অনুচ্ছেদ</td><td>শিক্ষা বিনিয়োগ নিরাপত্তা, শিক্ষা সুবিধা নির্মাণ, শিক্ষা তথ্যপ্রযুক্তি, বিশেষ শিক্ষা, আন্তঃ-জাতি শিক্ষা নির্ধারণ</td></tr><tr><td>ছবিংশ-ত্রিশ অনুচ্ছেদ</td><td>শিক্ষা মূল্যায়ন ব্যবস্থা, শিক্ষা তদারকি ব্যবস্থা, আইনি দায়িত্ব এবং সংযুক্ত বিধান নির্ধারণ</td></tr></tbody></table><h3 id="৫-২-চিকিৎসা-নিরাপত্তা-আইন" tabindex="-1">৫.২ চিকিৎসা নিরাপত্তা আইন <a class="header-anchor" href="#৫-২-চিকিৎসা-নিরাপত্তা-আইন" aria-label="Permalink to &quot;৫.২ চিকিৎসা নিরাপত্তা আইন&quot;">​</a></h3><table tabindex="0"><thead><tr><th>অনুচ্ছেদ নম্বর</th><th>মূল বিষয়বস্তু</th></tr></thead><tbody><tr><td>প্রথম অনুচ্ছেদ</td><td>আইনি উদ্দেশ্য: সর্বজনীন চিকিৎসা নিরাপত্তা ব্যবস্থা স্থাপন করা, সব সত্ত্বের স্বাস্থ্যের অধিকার নিশ্চিত করা, এবং সমস্ত জাতির সামগ্রিক স্বাস্থ্য স্তর উন্নত করা</td></tr><tr><td>দ্বিতীয়-পঞ্চম অনুচ্ছেদ</td><td>সর্বজনীন চিকিৎসা বীমা নীতি, মৌলিক চিকিৎসা বিনামূল্যে নীতি, চীনা ও পশ্চিমা চিকিৎসার সমন্বয় নীতি, সাধনা চিকিৎসা অন্তর্ভুক্তির নীতি প্রতিষ্ঠিত</td></tr><tr><td>ষষ্ঠ-দশম অনুচ্ছেদ</td><td>মৌলিক চিকিৎসা বীমা, গুরুতর রোগ বীমা, চিকিৎসা সহায়তা, বাণিজ্যিক স্বাস্থ্য বীমার বহু-স্তরের চিকিৎসা বীমা ব্যবস্থা নির্ধারণ</td></tr><tr><td>একাদশ-পঞ্চদশ অনুচ্ছেদ</td><td>চিকিৎসা প্রতিষ্ঠান ব্যবস্থাপনা, চিকিৎসা কর্মী ব্যবস্থা, চিকিৎসা মান এবং নিরাপত্তা, সাধনা চিকিৎসার বিশেষ মানদণ্ড নির্ধারণ</td></tr><tr><td>ষোড়শ-বিংশ অনুচ্ছেদ</td><td>ওষুধ ব্যবস্থাপনা, চিকিৎসা যন্ত্র ব্যবস্থাপনা, শক্তি চিকিৎসা পণ্য ব্যবস্থাপনা, অপরিহার্য ওষুধ ব্যবস্থা নির্ধারণ</td></tr><tr><td>একবিংশ-পঞ্চবিংশ অনুচ্ছেদ</td><td>গণস্বাস্থ্য ব্যবস্থা, রোগ প্রতিরোধ এবং নিয়ন্ত্রণ, স্বাস্থ্য শিক্ষা, আন্তঃ-জাতি চিকিৎসা, বিশেষ গোষ্ঠীর চিকিৎসা নিরাপত্তা নির্ধারণ</td></tr><tr><td>ছবিংশ-ত্রিশ অনুচ্ছেদ</td><td>চিকিৎসা বিবাদ পরিচালনা, চিকিৎসা তদারকি, আইনি দায়িত্ব এবং সংযুক্ত বিধান নির্ধারণ</td></tr></tbody></table><h3 id="৫-৩-আবাসন-নিরাপত্তা-আইন" tabindex="-1">৫.৩ আবাসন নিরাপত্তা আইন <a class="header-anchor" href="#৫-৩-আবাসন-নিরাপত্তা-আইন" aria-label="Permalink to &quot;৫.৩ আবাসন নিরাপত্তা আইন&quot;">​</a></h3><table tabindex="0"><thead><tr><th>অনুচ্ছেদ নম্বর</th><th>মূল বিষয়বস্তু</th></tr></thead><tbody><tr><td>প্রথম অনুচ্ছেদ</td><td>আইনি উদ্দেশ্য: সব সত্ত্বের মৌলিক আবাসনের অধিকার নিশ্চিত করা, বহু-স্তরের আবাসন নিরাপত্তা ব্যবস্থা গঠন করা, এবং সবার জন্য আবাসন অর্জন করা</td></tr><tr><td>দ্বিতীয়-পঞ্চম অনুচ্ছেদ</td><td>আবাসনের অধিকার নিরাপত্তা নীতি, আবাসন ন্যায়সঙ্গতা নীতি, ভাড়া এবং ক্রয় একসাথে নীতি, টেকসই আবাসন নীতি প্রতিষ্ঠিত</td></tr><tr><td>ষষ্ঠ-দশম অনুচ্ছেদ</td><td>পাবলিক ভাড়া বাসস্থান, সাশ্রয়ী ভাড়া বাসস্থান, শেয়ার্ড সম্পত্তি বাসস্থান, বাণিজ্যিক বাসস্থানের আবাসন সরবরাহ ব্যবস্থা নির্ধারণ</td></tr><tr><td>একাদশ-পঞ্চদশ অনুচ্ছেদ</td><td>আবাসন প্রভিডেন্ট ফান্ড ব্যবস্থা, আবাসন ভাতা ব্যবস্থা, প্রথম বাসস্থান সহায়তা নীতি, সাধকদের বিশেষ আবাসন নীতি নির্ধারণ</td></tr><tr><td>ষোড়শ-বিংশ অনুচ্ছেদ</td><td>আবাসন নির্মাণ মানদণ্ড, আবাসনে স্থান প্রযুক্তির প্রয়োগ, সবুজ বিল্ডিং, বার্ধক্য-বান্ধব এবং অপ্রতিবন্ধী আবাসন নির্ধারণ</td></tr><tr><td>একবিংশ-পঞ্চবিংশ অনুচ্ছেদ</td><td>রিয়েল এস্টেট বাজার নিয়ন্ত্রণ, আবাসন ভাড়া বাজার নিয়ন্ত্রণ, সম্পত্তি সেবা ব্যবস্থাপনা, আবাসন রক্ষণাবেক্ষণ নিরাপত্তা নির্ধারণ</td></tr><tr><td>ছবিংশ-ত্রিশ অনুচ্ছেদ</td><td>আবাসন নিরাপত্তা তদারকি, আইনি দায়িত্ব এবং সংযুক্ত বিধান নির্ধারণ</td></tr></tbody></table><h3 id="৫-৪-পরিবেশ-সুরক্ষা-আইন" tabindex="-1">৫.৪ পরিবেশ সুরক্ষা আইন <a class="header-anchor" href="#৫-৪-পরিবেশ-সুরক্ষা-আইন" aria-label="Permalink to &quot;৫.৪ পরিবেশ সুরক্ষা আইন&quot;">​</a></h3><table tabindex="0"><thead><tr><th>অনুচ্ছেদ নম্বর</th><th>মূল বিষয়বস্তু</th></tr></thead><tbody><tr><td>প্রথম অনুচ্ছেদ</td><td>আইনি উদ্দেশ্য: পরিবেশ সুরক্ষা এবং উন্নতি করা, দূষণ এবং অন্যান্য জনস্বার্থের বিপদ প্রতিরোধ ও নিয়ন্ত্রণ করা, জনস্বাস্থ্য নিশ্চিত করা, মহাজাগতিক পরিবেশগত সভ্যতা নির্মাণ প্রচার করা, এবং টেকসই উন্নয়ন প্রচার করা</td></tr><tr><td>দ্বিতীয়-পঞ্চম অনুচ্ছেদ</td><td>সুরক্ষা অগ্রাধিকার নীতি, প্রতিরোধ প্রথম নীতি, সমন্বিত পরিচালনা নীতি, জনস্বার্থ অংশগ্রহণ নীতি, ক্ষতির দায়িত্ব নীতি প্রতিষ্ঠিত</td></tr><tr><td>ষষ্ঠ-দশম অনুচ্ছেদ</td><td>পরিবেশ তদারকি এবং ব্যবস্থাপনা ব্যবস্থা, পরিবেশ মানদণ্ড ব্যবস্থা, পরিবেশ প্রভাব মূল্যায়ন ব্যবস্থা, পরিবেশ পর্যবেক্ষণ ব্যবস্থা, আন্তঃ-সমতল পরিবেশ ব্যবস্থাপনা নির্ধারণ</td></tr><tr><td>একাদশ-পঞ্চদশ অনুচ্ছেদ</td><td>বায়ু দূষণ প্রতিরোধ ও নিয়ন্ত্রণ, পানি দূষণ প্রতিরোধ ও নিয়ন্ত্রণ, মাটি দূষণ প্রতিরোধ ও নিয়ন্ত্রণ, শক্তি দূষণ প্রতিরোধ ও নিয়ন্ত্রণ, আইন দূষণ প্রতিরোধ ও নিয়ন্ত্রণ নির্ধারণ</td></tr><tr><td>ষোড়শ-বিংশ অনুচ্ছেদ</td><td>কঠিন বর্জ্য পরিচালনা, শব্দ দূষণ প্রতিরোধ ও নিয়ন্ত্রণ, তেজস্ক্রিয় দূষণ প্রতিরোধ ও নিয়ন্ত্রণ, পরিবেশগত সুরক্ষা, জীববৈচিত্র্য সুরক্ষা নির্ধারণ</td></tr><tr><td>একবিংশ-পঞ্চবিংশ অনুচ্ছেদ</td><td>সাধনা কার্যক্রমের পরিবেশ প্রভাব নিয়ন্ত্রণ, শক্তি খনির পরিবেশগত সুরক্ষা, আন্তঃ-সমতল প্রত্নতত্ত্বের পরিবেশগত প্রয়োজনীয়তা নির্ধারণ</td></tr><tr><td>ছবিংশ-ত্রিশ অনুচ্ছেদ</td><td>তথ্য প্রকাশ এবং জনস্বার্থ অংশগ্রহণ, পরিবেশগত জনস্বার্থ মামলা, আইনি দায়িত্ব এবং সংযুক্ত বিধান নির্ধারণ</td></tr></tbody></table><h3 id="৫-৫-একচেটিয়াবিরোধী-আইন" tabindex="-1">৫.৫ একচেটিয়াবিরোধী আইন <a class="header-anchor" href="#৫-৫-একচেটিয়াবিরোধী-আইন" aria-label="Permalink to &quot;৫.৫ একচেটিয়াবিরোধী আইন&quot;">​</a></h3><table tabindex="0"><thead><tr><th>অনুচ্ছেদ নম্বর</th><th>মূল বিষয়বস্তু</th></tr></thead><tbody><tr><td>প্রথম অনুচ্ছেদ</td><td>আইনি উদ্দেশ্য: একচেটিয়া আচরণ প্রতিরোধ এবং বিরত রাখা, বাজারের ন্যায়সঙ্গত প্রতিযোগিতা সুরক্ষা, অর্থনৈতিক কার্যকারিতা উন্নত করা, ভোক্তাদের স্বার্থ এবং সামাজিক জনস্বার্থ রক্ষা করা, এবং সিম্বায়োসিস বাজার অর্থনীতির সুস্থ উন্নয়ন প্রচার করা</td></tr><tr><td>দ্বিতীয়-পঞ্চম অনুচ্ছেদ</td><td>প্রতিযোগিতা নীতির মৌলিক অবস্থান, ন্যায়সঙ্গত প্রতিযোগিতা পর্যালোচনা ব্যবস্থা, একচেটিয়া চুক্তি নিষিদ্ধ, বাজারের প্রভাবশালী অবস্থার অপব্যবহার নিষিদ্ধ, ব্যবসায়ী ঘনীভবন নিয়ন্ত্রণ প্রতিষ্ঠিত</td></tr><tr><td>ষষ্ঠ-দশম অনুচ্ছেদ</td><td>একচেটিয়া চুক্তির সনাক্তকরণ এবং ছাড়, অনুভূমিক একচেটিয়া চুক্তি, উল্লম্ব একচেটিয়া চুক্তি, শিল্প সমিতির একচেটিয়া আচরণ নির্ধারণ</td></tr><tr><td>একাদশ-পঞ্চদশ অনুচ্ছেদ</td><td>বাজারের প্রভাবশালী অবস্থার সনাক্তকরণ, বাজারের প্রভাবশালী অবস্থার অপব্যবহারের আচরণের প্রকার, শিকারকারী মূল্য নির্ধারণ নিষিদ্ধ নির্ধারণ</td></tr><tr><td>ষোড়শ-বিংশ অনুচ্ছেদ</td><td>ব্যবসায়ী ঘনীভবন ঘোষণা মানদণ্ড, পর্যালোচনা প্রক্রিয়া, সংযুক্ত সীমাবদ্ধকারী শর্তাবলী, ঘনীভবন নিষিদ্ধের সিদ্ধান্ত নির্ধারণ</td></tr><tr><td>একবিংশ-পঞ্চবিংশ অনুচ্ছেদ</td><td>সাধনা পদ্ধতি একচেটিয়ার বিশেষ নিষিদ্ধ: সাধনা পদ্ধতি একচেটিয়া নিষিদ্ধ, সাধনা সম্পদ একচেটিয়া নিষিদ্ধ, গুরু নেটওয়ার্ক একচেটিয়া নিষিদ্ধ নির্ধারণ</td></tr><tr><td>ছবিংশ-ত্রিশ অনুচ্ছেদ</td><td>একচেটিয়াবিরোধী আইন প্রয়োগকারী সংস্থা, তদন্ত প্রক্রিয়া, আইনি দায়িত্ব, ক্ষমা ব্যবস্থা এবং সংযুক্ত বিধান নির্ধারণ</td></tr></tbody></table><h2 id="উপসংহার" tabindex="-1">উপসংহার <a class="header-anchor" href="#উপসংহার" aria-label="Permalink to &quot;উপসংহার&quot;">​</a></h2><p>আইনি অনুচ্ছেদের সূচিটি অ্যাঙ্কর সিম্বায়োসিস সভ্যতার আইন শাসন ব্যবস্থার একটি রেফারেন্স মানচিত্র। মৌলিক আইন হিসেবে সিম্বায়োসিস সংবিধান থেকে শুরু করে জনজীবন নিয়ন্ত্রণকারী শ্রম আইন এবং ভোক্তা সুরক্ষা আইন, এবং তারপর পাঁচটি সহায়ক আইন, একসাথে &quot;সংবিধানকে কমান্ডার হিসেবে, মৌলিক আইনকে মেরুদণ্ড হিসেবে, এবং সহায়ক আইনকে সহায়তা হিসেবে&quot; একটি সম্পূর্ণ আইনি ব্যবস্থা গঠন করে। এই ব্যবস্থা নিশ্চিত করে যে সিম্বায়োসিস সভ্যতার সমস্ত কার্যক্রম আইন শাসনের পথে চলে, এবং সমস্ত জাতির সম্মিলিত অগ্রগতির জন্য একটি শক্তিশালী প্রাতিষ্ঠানিক নিশ্চয়তা প্রদান করে।</p><h2 id="সম্পর্কিত-নথি" tabindex="-1">সম্পর্কিত নথি <a class="header-anchor" href="#সম্পর্কিত-নথি" aria-label="Permalink to &quot;সম্পর্কিত নথি&quot;">​</a></h2><ul><li>40-সিম্বায়োসিস সংবিধান সাধারণ পরিকল্পনা</li><li>41-সিম্বায়োসিস শ্রম আইন</li><li>48-বিচারিক ব্যবস্থা এবং বিচার প্রক্রিয়া</li></ul>',28)])])}const c=d(h,[["render",o]]);export{q as __pageData,c as default};
